1	import { useRef, useEffect, useState } from 'react'
2	import { useVirtualizer } from '@tanstack/react-virtual'
3	import { Box } from '@mantine/core'
4	import * as pageCache from '../../lib/pageCache'
5	import { PDFFile } from './usePDFFile'
6	import { makeResizeDragHandler } from '../../lib/resizableWidth'
7	import { DEFAULT_WIDTH, DRAG_HANDLE_WIDTH, ITEM_PADDING, LABEL_HEIGHT, PAGE_ASPECT } from '../../constants'
8	import PageThumbnail from '../PageThumbnail'
9	
10	const MIN_TOTAL_WIDTH = 240
11	const MAX_TOTAL_WIDTH = 960
12	export const DEFAULT_TOTAL_WIDTH = DEFAULT_WIDTH * 2
13	
14	export type FirstPageIn = 'a' | 'b'
15	export type SelectedPage = { file: FirstPageIn, page: number }
16	
17	interface Props {
18	  fileA: PDFFile
19	  fileB: PDFFile
20	  selectedPage: SelectedPage
21	  onSelectPage: (file: FirstPageIn, page: number) => void
22	  firstPageIn: FirstPageIn
23	  totalWidth: number
24	  onWidthChange: (w: number) => void
25	  colWidth: number
26	  reverseB: boolean
27	}
28	
29	function makePageNumberLabel(isFirst: boolean, countOther: number) {
30	  return (index: number) => {
31	    const n = index + 1
32	    if (n <= countOther) return isFirst ? 2 * n - 1 : 2 * n
33	    return 2 * countOther + (n - countOther)
34	  }
35	}
36	
37	export default function MergeModeThumbnailPanel({
38	  fileA, fileB,
39	  selectedPage, onSelectPage,
40	  firstPageIn, totalWidth, onWidthChange, colWidth, reverseB,
41	}: Props) {
42	  const selectedPageA = selectedPage.file === 'a' ? selectedPage.page : null
43	  const selectedPageB = selectedPage.file === 'b' ? selectedPage.page : null
44	  const thumbWidth = colWidth - ITEM_PADDING * 2
45	  const thumbHeight = Math.round(thumbWidth * PAGE_ASPECT)
46	  const itemHeight = thumbHeight + LABEL_HEIGHT + ITEM_PADDING
47	
48	  const bothLoaded = fileA.path !== null && fileB.path !== null
49	  const halfThumbHeight = Math.round(thumbHeight / 2)
50	  const offsetA = bothLoaded && firstPageIn === 'b' ? halfThumbHeight : 0
51	  const offsetB = bothLoaded && firstPageIn === 'a' ? halfThumbHeight : 0
52	
53	  const totalHeight = Math.max(offsetA + fileA.count * itemHeight, offsetB + fileB.count * itemHeight, 0)
54	
55	  const scrollRef = useRef<HTMLDivElement>(null)
56	
57	  pageCache.usePageCacheRender()
58	
59	  const aIsFirst = firstPageIn === 'a'
60	  const pageLabelA = bothLoaded ? makePageNumberLabel(aIsFirst, aIsFirst ? fileB.count : fileA.count) : undefined
61	  const pageLabelB = bothLoaded ? makePageNumberLabel(!aIsFirst, aIsFirst ? fileA.count : fileB.count) : undefined
62	
63	  const startDrag = makeResizeDragHandler(totalWidth, onWidthChange, MIN_TOTAL_WIDTH, MAX_TOTAL_WIDTH)
64	
65	  return (
66	    <Box style={{ display: 'flex', height: '100%', flexShrink: 0 }}>
67	      <Box style={{ display: 'flex', flexDirection: 'column', width: totalWidth, height: '100%' }}>
68	        {/* Single scroll area with two absolute columns */}
69	        <div
70	          ref={scrollRef}
71	          style={{
72	            flex: 1,
73	            minHeight: 0,
74	            overflowY: 'auto',
75	            overflowX: 'hidden',
76	            background: 'var(--mantine-color-gray-3)',
77	          }}
78	        >
79	          <div style={{ height: totalHeight, position: 'relative' }}>
80	            <div style={{ position: 'absolute', left: 0, top: 0, width: colWidth, height: '100%' }}>
81	              <ThumbColumn
82	                scrollRef={scrollRef}
83	                file={fileA}
84	                pdfPath={fileA.path ?? ''}
85	                itemHeight={itemHeight}
86	                paddingStart={offsetA}
87	                thumbWidth={thumbWidth}
88	                thumbHeight={thumbHeight}
89	                selectedPage={selectedPageA}
90	                onSelectPage={(page) => onSelectPage('a', page)}
91	                pageLabel={pageLabelA}
92	              />
93	            </div>
94	            <div style={{ position: 'absolute', left: colWidth, top: 0, width: colWidth, height: '100%' }}>
95	              <ThumbColumn
96	                scrollRef={scrollRef}
97	                file={fileB}
98	                pdfPath={fileB.path ?? ''}
