import { useState, useCallback } from 'react'
import { PickFolder, ScanLocalRoot } from '../../../wailsjs/go/main/App'

export interface LocalFile {
  path: string
  name: string
  sizeBytes: number
  pageCount: number
  corrupt: boolean
}

export interface LocalFileGroup {
  name: string
  files: LocalFile[]
  subgroups: LocalFileGroup[]
}

export interface FileTreeHandle {
  root: string | null
  tree: LocalFileGroup | null
  loading: boolean
  error: string | null
  pickRoot: () => Promise<void>
}

export function useFileTree(): FileTreeHandle {
  const [root, setRoot] = useState<string | null>(null)
  const [tree, setTree] = useState<LocalFileGroup | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const pickRoot = useCallback(async () => {
    const folder = await PickFolder('Choose Root Folder')
    if (!folder) return

    setRoot(folder)
    setLoading(true)
    setError(null)
    try {
      setTree(await ScanLocalRoot(folder))
    } catch (e) {
      setTree(null)
      setError(String(e))
    } finally {
      setLoading(false)
    }
  }, [])

  return { root, tree, loading, error, pickRoot }
}

import { useState, ReactNode } from 'react'
import { Box } from '@mantine/core'
import { DRAG_HANDLE_WIDTH } from '../../constants'
import { makeResizeDragHandler } from '../../lib/resizableWidth'

const DEFAULT_LEFT_PANEL_WIDTH = 300
const MIN_LEFT_PANEL_WIDTH = 180
const MAX_LEFT_PANEL_WIDTH = 600

interface Props {
  left: ReactNode
  children: ReactNode
}

// Owns the drag-resize width state itself so that dragging the handle only
// re-renders this component, not the (possibly large, unmemoized) `left`
// and `children` trees passed in from the parent's last render.
export default function ResizableLeftPanel({ left, children }: Props) {
  const [leftWidth, setLeftWidth] = useState(DEFAULT_LEFT_PANEL_WIDTH)
  const startDrag = makeResizeDragHandler(leftWidth, setLeftWidth, MIN_LEFT_PANEL_WIDTH, MAX_LEFT_PANEL_WIDTH)

  return (
    <Box style={{ display: 'flex', height: '100%' }}>
      <Box
        style={{
          width: leftWidth,
          flexShrink: 0,
          height: '100%',
          overflowY: 'auto',
          padding: 12,
        }}
      >
        {left}
      </Box>

      <Box
        onMouseDown={startDrag}
        style={{
          width: DRAG_HANDLE_WIDTH,
          height: '100%',
          cursor: 'col-resize',
          flexShrink: 0,
          background: 'var(--mantine-color-gray-3)',
        }}
      />

      {children}
    </Box>
  )
}

